// Product photographs of the supplied wound dressings, from page 117 of the
// CPG (Wound Care, p112-117). The v6.2 content rebuild captured this panel only
// as the text `suppliedDressings` table because pdf.js drops graphics silently;
// these are the photos themselves, so a responder can recognise the physical
// product in their kit.
//
// Extracted from source/Compiled_v6_2.pdf p117, cropped, downscaled to 300px
// wide and JPEG-compressed, then inlined as base64 data URIs. Inlining (rather
// than a lazy-loaded asset) guarantees they render offline in the field with no
// service-worker change - the whole point of this app.
//
// Rendered by the photo-card shape in ProtocolView.renderValue (an array whose
// items each carry a `src`). Referenced from the 'wound-care' protocol's
// `dressingPhotos` key in contentData.js.
export const woundDressingPhotos = [
  {
    src: 'data:image/jpeg;base64,',
    caption: 'Silicone foam (Biatain)',
    size: '7.5 × 7.5 cm and 12.5 × 12.5 cm',
  },
  {
    src: 'data:image/jpeg;base64,',
    caption: 'Adhesive wound tape (Steri-Strips)',
    size: '6 × 100 mm strips',
  },
  {
    src: 'data:image/jpeg;base64,',
    caption: 'Non adherent dressing (Melolin)',
    size: '10 × 10 cm',
  },
];
